// Tải ảnh thô cần thiết (raw_image_1/2/3) cho mỗi item + gắn LOGO CỐ ĐỊNH (đã nhúng sẵn,
// KHÔNG qua Drive nữa) + ghi hotline tĩnh vào json, gộp thành binary trên CÙNG 1 item để
// "Edit an image" dùng trong 1 lần gọi Gemini.
//
// ĐÃ BỎ việc tải "template_image" (không còn khái niệm chọn template cụ thể — phong cách
// giờ được mô tả bằng CHỮ ngay trong prompt của "Edit an image", để model không bị bám
// theo bố cục của 1 ảnh mẫu cụ thể nào — xem yêu cầu "phá cách, tự thiết kế").
//
// !!! CẦN CẤU HÌNH 1 LẦN (chỉ nếu muốn hiện badge hotline trên mọi ảnh): điền số hotline
// thật vào HOTLINE_TEXT bên dưới, ví dụ "1900 xxxx" hoặc "090x xxx xxx". Để trống "" nếu
// CHƯA có số hotline chính thức muốn công khai — "Edit an image" sẽ tự động KHÔNG vẽ badge
// hotline khi field này rỗng (tránh AI tự bịa số điện thoại giả không có thật).
const HOTLINE_TEXT = "0868 515 668";

function getDirectUrl(fileId) {
  if (!fileId) return "";
  return `https://drive.usercontent.google.com/download?id=${fileId}&export=download`;
}

async function fetchBinary(url) {
  if (!url) return null;
  try {
    const response = await this.helpers.httpRequest({
      method: 'GET',
      url,
      encoding: 'arraybuffer',
      returnFullResponse: true,
    });
    const buffer = Buffer.isBuffer(response.body) ? response.body : Buffer.from(response.body);
    const contentType = (response.headers && response.headers['content-type']) || 'image/jpeg';
    return await this.helpers.prepareBinaryData(buffer, undefined, contentType);
  } catch (err) {
    return null;
  }
}

const items = $input.all();
const results = [];

for (const item of items) {
  const j = item.json;
  const binary = {};
  const slotCount = Number(j.raw_image_count) || 0;

  // ĐÃ BỎ gắn logo_image vào đây — logo thật giờ được ghép ở bước RIÊNG, SAU khi Gemini
  // vẽ xong ảnh (xem node "Tính Vị Trí Logo" -> "Resize Logo Thật" -> "Ghép Logo Thật Lên
  // Ảnh"). Gửi logo cho Gemini xem chỉ khiến nó tự vẽ lại một phiên bản logo của riêng nó.

  const raw1 = await fetchBinary.call(this, j.raw_image_1_url);
  const raw2Fetched = slotCount >= 2 ? await fetchBinary.call(this, j.raw_image_2_url) : null;
  const raw3Fetched = slotCount >= 3 ? await fetchBinary.call(this, j.raw_image_3_url) : null;

  // Chốt đảm bảo: raw_image_2/raw_image_3 LUÔN có giá trị binary (dù là placeholder
  // trùng ảnh khác) để node "Edit an image" không báo lỗi thiếu field.
  const raw2 = raw2Fetched || raw1 || null;
  const raw3 = raw3Fetched || raw2 || raw1 || null;

  if (raw1) binary.raw_image_1 = raw1;
  if (raw2) binary.raw_image_2 = raw2;
  if (raw3) binary.raw_image_3 = raw3;

  j.hotline_text = HOTLINE_TEXT;

  // pairedItem: giữ liên kết item gốc để các node sau (Upload file...) tra ngược được
  results.push({ json: j, binary, pairedItem: { item: items.indexOf(item) } });
}

return results;

// Node: Code chuẩn hóa 3 Options + Link Thư mục Ảnh Demo
const items = $input.all(); // Nhận N items (mặc định 5 mẫu ảnh) từ node Upload file

// 1. LẤY DỮ LIỆU BÀI VIẾT TỪ NODE Gemini Content Creator
let geminiItem = {};
try {
    geminiItem = $('Gemini Content Creator1').first()?.json || {};
} catch (e) { }

let rawText = geminiItem.content?.parts?.[0]?.text
    || geminiItem.candidates?.[0]?.content?.parts?.[0]?.text
    || geminiItem.text || geminiItem.output || geminiItem.message?.content || "";

if (typeof rawText === 'object') {
    rawText = JSON.stringify(rawText);
}

const cleaned = String(rawText).replace(/```json/gi, '').replace(/```/g, '').trim();
let parsed = {};
try {
    parsed = JSON.parse(cleaned);
} catch (e) { }

// 2. LẤY ROW NUMBER DÒNG ĐANG CHẠY
let rowId = 5;
try {
    rowId = $('Xử lý gom các nội dung trùng1').first()?.json?.["# row_number"]
        || $('Xử lý gom các nội dung trùng1').first()?.json?.row_number
        || $('Get row(s) in sheet1').first()?.json?.["# row_number"]
        || $('Get row(s) in sheet1').first()?.json?.row_number || 5;
} catch (e) { }

// 3. LINK THƯ MỤC ẢNH DEMO (đọc qua "Tách ảnh từ nhiều link" — an toàn, không văng
//    lỗi khi nhánh tạo folder không chạy vì folder đã tồn tại sẵn)
let folderLink = "";
try {
    folderLink = $('Tách ảnh từ nhiều link1').first()?.json?.drive_folder_link || "";
} catch (e) { }
if (!folderLink) {
    const parentFolderId = items[0]?.json?.parents?.[0] || "";
    if (parentFolderId) folderLink = `https://drive.google.com/drive/folders/${parentFolderId}`;
}

// 4. BÓC TÁCH NỘI DUNG 3 OPTION & CHUẨN HÓA VĂN BẢN (GỠ NHÃN AI, DÒNG PHÂN LOẠI, BRANDING ECOLAR)
const op1 = parsed.option_1 || {};
const op2 = parsed.option_2 || {};
const op3 = parsed.option_3 || {};
let hashtags = parsed.hashtags || "#GaAiCapVan #Ecolar #KyThuatChanNuoi";
hashtags = String(hashtags)
    .replace(/NongNghiepEcolar/gi, "Ecolar")
    .replace(/NongNghiep/gi, "")
    .replace(/#+/g, "#")
    .trim();

function cleanAndFormat(opObj) {
    if (!opObj || (typeof opObj === 'object' && Object.keys(opObj).length === 0)) return "";
    if (typeof opObj === 'string') {
        try { opObj = JSON.parse(opObj); } catch (e) { return opObj; }
    }

    let hook = opObj.hook || "";
    let body = opObj.content || "";
    if (typeof body === 'object') body = JSON.stringify(body);

    // Gỡ prefix HOOK & dòng phân loại [ ... ] nếu có
    hook = String(hook)
        .replace(/^📌?\s*HOOK\s*:\s*/gi, "")
        .replace(/^\[.*?\]\s*/gim, "")
        .trim();

    // Gỡ prefix NỘI DUNG & dòng phân loại [ ... ] & hashtag thừa ở cuối
    body = String(body)
        .replace(/^📝?\s*NỘI DUNG\s*:\s*/gi, "")
        .replace(/^\[.*?\]\s*/gim, "")
        .replace(/(#[\w\u00C0-\u024F\u1E00-\u1EFF]+\s*)+$/gi, "")
        .trim();

    // Ghép Hook và Nội dung (chỉ Hook + Body, có icon tinh tế)
    let fullText = "";
    if (hook && !body.toLowerCase().includes(hook.toLowerCase())) {
        const hasEmoji = /^[\u{1F300}-\u{1F9FF}\u{2600}-\u{26FF}\u{2700}-\u{27BF}]/u.test(hook);
        const hookFormatted = hasEmoji ? hook : `📌 ${hook}`;
        fullText = `${hookFormatted}\n\n${body}`;
    } else {
        fullText = body;
    }

    // Gỡ triệt để các nhãn AI & chuẩn hóa tên thương hiệu "Ecolar" độc lập
    fullText = fullText
        .replace(/\[\s*Nội dung (do|được)?\s*AI\s*(tạo|sáng tạo|sinh)?\s*\]/gi, "")
        .replace(/\(\s*Nội dung (do|được)?\s*AI\s*(tạo|sáng tạo|sinh)?\s*\)/gi, "")
        .replace(/Nội dung (do|được)?\s*AI\s*(tạo|sáng tạo|sinh)?/gi, "")
        .replace(/AI-generated\s*content/gi, "")
        .replace(/Nông\s+Nghiệp\s+Ecolar/gi, "Ecolar")
        .replace(/Nông\s+nghiệp\s+Ecolar/gi, "Ecolar")
        .replace(/nông\s+nghiệp\s+Ecolar/gi, "Ecolar")
        .replace(/Công\s+ty\s+Ecolar/gi, "Ecolar")
        .replace(/\n{3,}/g, "\n\n")
        .trim();

    return fullText;
}

const text1 = cleanAndFormat(op1);
const text2 = cleanAndFormat(op2);
const text3 = cleanAndFormat(op3);

// 5. TRẢ VỀ DỮ LIỆU ĐÃ MAP DÀNH CHO GOOGLE SHEETS
return [{
    json: {
        "row_number": rowId,
        "Option_1": text1 ? `${text1}\n\n${hashtags}`.trim() : rawText,
        "Option_2": text2 ? `${text2}\n\n${hashtags}`.trim() : "",
        "Option_3": text3 ? `${text3}\n\n${hashtags}`.trim() : "",
        "Anh_Demo": folderLink, // Link thư mục Drive chứa toàn bộ ảnh của bài này (cột AF)
        "Trạng thái": "waiting_review"
    }
}];

// Node: Bốc Option đã duyệt + format nội dung + lấy folder ảnh của bài viết
return $input.all().map((item, index) => {
  const row = item.json;
  const rowId = row["row_number"] || row["ID"] || (index + 5);
  const keys = Object.keys(row);
  const findKey = (needle, fallback) =>
    keys.find(k => k.trim().toLowerCase() === needle) ||
    keys.find(k => k.trim().toLowerCase().includes(needle)) || fallback;

  const keyOp1     = findKey("option 1", "Option 1 ");
  const keyOp2     = findKey("option 2", "Option 2");
  const keyOp3     = findKey("option 3", "Option 3");
  const keyDuyetOp = findKey("duyệt option", "Duyệt Option");
  const keyAnhDemo = findKey("ảnh demo", "Ảnh Demo");

  const rawSelectedOp = String(row[keyDuyetOp] || "").trim();
  if (!rawSelectedOp) {
    return { json: {
      ID: rowId, selectedOp: "CHƯA_CHỌN", folder_id: "",
      fullMessage: "⚠️ CHƯA CHỌN OPTION Ở CỘT 'Duyệt Option'",
      "Kết quả": "no_option_selected_error"
    } };
  }

  let optNum = 1;
  if (rawSelectedOp.includes("2")) optNum = 2;
  else if (rawSelectedOp.includes("3")) optNum = 3;

  const textByOpt = { 1: row[keyOp1], 2: row[keyOp2], 3: row[keyOp3] };
  let cleaned = String(textByOpt[optNum] || "")
    .replace(/🖼️\s*(MẪU\s*\d+|PREVIEW\s*ÁNH)\s*:\s*\S+/gi, "")
    .replace(/^\[.*?\]\s*/, "")
    .replace(/^📌\s*HOOK\s*:\s*/gim, "")
    .replace(/^📝\s*NỘI DUNG\s*:\s*/gim, "")
    .replace(/👉\s*Chi tiết tại:[\s\S]*$/i, "")
    .trim();

  const hashtagRegex = /((?:#[\wÀ-ɏḀ-ỿ]+\s*)+)$/i;
  const m = cleaned.match(hashtagRegex);
  let mainText = cleaned, hashtags = "";
  if (m) { hashtags = m[1].trim(); mainText = cleaned.slice(0, m.index).trim(); }

  const contactInfo = `------------------------------------
Ecolar – Lối sống xanh bền vững
🌐 Website: https://ecolar.vn/
📞Hotline: 0868 515 668
📧Email: lienhe@ecolar.vn
📘Zalo OA: https://zalo.me/1699772582506373938
ⓕFacebook: https://www.facebook.com/Loisongxanhecolar
▶️Youtube: https://www.youtube.com/@LoiSongXanhEcolar
🎵Tiktok: https://www.tiktok.com/@gaaicapecolar`;

  let fullMessage = `${mainText}\n\n${contactInfo}`;
  if (hashtags) fullMessage += `\n\n${hashtags}`;
  fullMessage = fullMessage.replace(/\n{3,}/g, "\n\n").trim();

  // Folder ảnh riêng của bài này (lấy từ cột "Ảnh Demo")
  const rawFolder = String(row[keyAnhDemo] || "").trim();
  const fm = rawFolder.match(/folders\/([a-zA-Z0-9_-]{20,})/)
          || rawFolder.match(/[?&]id=([a-zA-Z0-9_-]{20,})/);
  const folderId = fm ? fm[1]
                      : (/^[a-zA-Z0-9_-]{20,}$/.test(rawFolder) ? rawFolder : "");

  return { json: {
    ID: rowId,
    selectedOp: rawSelectedOp,
    folder_id: folderId,
    fullMessage,
    "Kết quả": folderId ? "ready_to_publish" : "ready_to_publish_no_folder"
  } };
});

const allItems = $input.all();
let lastValidData = {};

return allItems.map((item) => {
  const row = item.json;
  if (row["Mục đích chính"]) lastValidData["Mục đích chính"] = row["Mục đích chính"];
  if (row["Thông tin thương hiệu/sản phẩm/dịch vụ/USP"]) lastValidData["Thông tin thương hiệu/sản phẩm/dịch vụ/USP"] = row["Thông tin thương hiệu/sản phẩm/dịch vụ/USP"];
  if (row["Chân dung & Insight khách hàng"]) lastValidData["Chân dung & Insight khách hàng"] = row["Chân dung & Insight khách hàng"];
  if (row["Văn phong"]) lastValidData["Văn phong"] = row["Văn phong"];

  return {
    json: {
      ...row,
      "Mục đích chính": row["Mục đích chính"] || lastValidData["Mục đích chính"] || "",
      "Thông tin thương hiệu/sản phẩm/dịch vụ/USP": row["Thông tin thương hiệu/sản phẩm/dịch vụ/USP"] || lastValidData["Thông tin thương hiệu/sản phẩm/dịch vụ/USP"] || "",
      "Chân dung & Insight khách hàng": row["Chân dung & Insight khách hàng"] || lastValidData["Chân dung & Insight khách hàng"] || "",
      "Văn phong": row["Văn phong"] || lastValidData["Văn phong"] || ""
    }
  };
});

