const availableStandards = [1, 2, 3]
  .map(i => ({ idx: i, text: standardsByOption[i] || "" }))
  .filter(s => s.text.trim());

if (resultItems.length > 0) {
  const baseCount = resultItems.length;
  let cursor = 0;

  while (resultItems.length < TARGET_IMAGE_COUNT && cursor < TARGET_IMAGE_COUNT * 3) {
    const base = resultItems[cursor % baseCount];
    const clone = JSON.parse(JSON.stringify(base));

    if (availableStandards.length > 1) {
      const curIdx = base.json.image_standard_index || 1;
      const pos = availableStandards.findIndex(s => s.idx === curIdx);
      const step = 1 + Math.floor(cursor / baseCount);
      const next = availableStandards[(Math.max(pos, 0) + step) % availableStandards.length];
      clone.json.image_standard = next.text;
      clone.json.image_standard_index = next.idx;
      clone.json.layout_menu = "";
    }

    clone.json.layout_note = String(base.json.layout_note || "").trim() +
      " (ĐÂY LÀ PHƯƠNG ÁN THIẾT KẾ THAY THẾ cho cùng nội dung — hãy dựng bố cục KHÁC HẲN " +
