// Node: Xóa Metadata AI (Hỗ trợ lặp và xử lý TOÀN BỘ N ảnh)
const items = $input.all();
const result = [];

for (let index = 0; index < items.length; index++) {
  const item = items[index];
  const binaryPropName = 'data';

  // Nếu item không chứa file nhị phân ảnh thì giữ nguyên
  if (!item.binary || !item.binary[binaryPropName]) {
    result.push(item);
    continue;
  }

  // Lấy buffer của từng ảnh theo chỉ số index
  const buf = await this.helpers.getBinaryDataBuffer(index, binaryPropName);

  // Lọc xóa toàn bộ khối Exif / C2PA nhãn AI trong JPEG
  if (buf[0] === 0xFF && buf[1] === 0xD8) {
    const cleaned = [0xFF, 0xD8];
    let i = 2;
    while (i < buf.length) {
      if (buf[i] === 0xFF) {
        const marker = buf[i + 1];
        if (marker === 0xDA) { // SOS - Start of Scan (bắt đầu dữ liệu ảnh thực)
          for (let j = i; j < buf.length; j++) cleaned.push(buf[j]);
          break;
        }
        if (marker >= 0xE0 && marker <= 0xEF) { // APP0-APP15 (Khối chứa nhãn AI & Exif)
          const len = (buf[i + 2] << 8) + buf[i + 3];
          i += 2 + len;
          continue;
        }
      }
      cleaned.push(buf[i]);
      i++;
    }

    const cleanBinary = await this.helpers.prepareBinaryData(
      Buffer.from(cleaned),
      item.binary[binaryPropName].fileName || `cleaned_${index}.jpg`,
      'image/jpeg'
    );
    result.push({ json: item.json, binary: { [binaryPropName]: cleanBinary } });
  } else {
    result.push(item);
  }
}

