// Doc kich thuoc ANH NEN THAT tu chinh buffer nhi phan (PNG/JPEG header), KHONG dua vao
// field width/height do node "Lay Kich Thuoc Anh Nen" tra ra (co the sai ten field tuy
// phien ban n8n, khien code cu luon roi ve mac dinh 1080x1080 va tinh sai ty le logo).
function readImageSize(buffer) {
  try {
    if (
      buffer.length > 24 &&
      buffer[0] === 0x89 && buffer[1] === 0x50 && buffer[2] === 0x4e && buffer[3] === 0x47
    ) {
      // PNG: IHDR width/height nam o byte 16-23
      return { width: buffer.readUInt32BE(16), height: buffer.readUInt32BE(20) };
    }
    if (buffer.length > 4 && buffer[0] === 0xff && buffer[1] === 0xd8) {
      // JPEG: quet cac marker de tim SOF0/SOF2
      let offset = 2;
      while (offset + 9 < buffer.length) {
        if (buffer[offset] !== 0xff) { offset++; continue; }
        const marker = buffer[offset + 1];
        if (marker === 0xd8 || marker === 0x01 || (marker >= 0xd0 && marker <= 0xd9)) {
          offset += 2;
          continue;
        }
        const segLen = buffer.readUInt16BE(offset + 2);
        if (marker >= 0xc0 && marker <= 0xcf && marker !== 0xc4 && marker !== 0xc8 && marker !== 0xcc) {
          return { height: buffer.readUInt16BE(offset + 5), width: buffer.readUInt16BE(offset + 7) };
        }
        offset += 2 + segLen;
      }
    }
  } catch (err) {
    // roi qua fallback ben duoi
  }
  return null;
}

// Logo base64 (ecolar-logo.png RGBA trong suot)
const LOGO_B64 = '';

const allItems = $input.all();
const results = [];

for (let idx = 0; idx < allItems.length; idx++) {
  const item = allItems[idx];
  const j = item.json;

  let bgWidth = 1080;
  let bgHeight = 1080;
  try {
    const bgBuffer = await this.helpers.getBinaryDataBuffer(idx, 'edited');
    const dim = readImageSize(bgBuffer);
    if (dim && dim.width > 0 && dim.height > 0) {
      bgWidth = dim.width;
      bgHeight = dim.height;
    }
  } catch (err) {
    // khong doc duoc buffer thi giu mac dinh 1080x1080 (an toan, logo van dung ty le)
  }

  // Tinh chieu rong logo theo ty le chieu rong anh, roi CHAN CUNG boi tran chieu cao —
  // neu bi tran chieu cao thi giam chieu rong lai theo dung ty le that cua file logo, de
  // logo khong bao gio to bat thuong du anh nen vuong hay bi lech ty le.
  let logo_target_width = Math.round(bgWidth * LOGO_WIDTH_RATIO);
  const logo_target_height_cap = Math.round(bgHeight * MAX_LOGO_HEIGHT_RATIO);
  if (logo_target_width / LOGO_ASPECT > logo_target_height_cap) {
    logo_target_width = Math.round(logo_target_height_cap * LOGO_ASPECT);
  }

  const logo_margin_x = Math.round(bgWidth * MARGIN_X_RATIO);
  const logo_margin_y = Math.round(bgHeight * MARGIN_Y_RATIO);

  const logoBuffer = Buffer.from(LOGO_B64, 'base64');
  const logoBinary = await this.helpers.prepareBinaryData(logoBuffer, 'ecolar-logo.png', 'image/png');

  results.push({
    json: {
      ...j,
      bg_width: bgWidth,
      bg_height: bgHeight,
      logo_target_width,
      logo_target_height_cap,
      logo_margin_x,
      logo_margin_y,
    },
    binary: {
      ...(item.binary || {}),
      logo_image: logoBinary,
    },
    pairedItem: item.pairedItem,
  });
}

return results;
